
import re, sys, pathlib, json
sys.stdout.reconfigure(encoding="utf-8")
p = pathlib.Path(r"C:\Users\lihao\Desktop\Graduation Project\OpticalWaveguideRouter3D\publication\report\2d_overall") / "二维光波导自动布线总体实验报告.md"
lines = p.read_text(encoding="utf-8").split("\n")
titles = json.loads(r'''["端口规模与连接输入","512 通道端点坐标快照公式","板面、线宽、间距与半径参数","损耗模型分量与参数来源","编号与术语对照","实验条件与证据等级汇总","原可执行程序逐路状态差分结果","复现对照层级与证据强度","复现损耗与原报告数值对照","一次 90° 转弯损耗：论文表 3-1 与复刻模型","原版交叉损耗表的搜索结果","交叉损耗模型三口径固定几何复算","仍然缺失的参数","512 通道半径扫描（复现侧，独立布线）","Step 12 四个方案的定义与性质","候选轨道与自适应半径比较（A / B / C / D）","Step 12 消融：候选数、顺序、位置正则、拆线重布、半径策略","统一 R6 与自适应半径的比较","收益归因：参数收益与算法收益","256 通道方案 A 平均损耗的分量构成","端点冻结前后的实验条件差异","固定端点与自由弯角比较（256 通道）","固定端点与自由弯角比较（512 通道）","相对 R5U 的收益（256 / 512）","自由弯角的代价（256 / 512）","最差链路追踪","交叉表风险稳健性（×1 / ×2 / ×5 / ×10）","真实重合反例的两条斜线段","直线—直线稳健分类的三层判据","事件层级与计数定义","段级接触与物理接触对照","旧产物合法性扫描","修复代价：256 F56 修复前后对比","256 F56 重新布线后的逐路变化","已更正的旧结论清单","口径对结论的影响（哪些排名会反转）","自适应半径与冻结半径下的受约束对照（256）","固定保护集合","冻结约束与保护性优化（256 通道）","冻结约束与保护性优化（512 通道）","各配置相对 base 的变化与验收","保护路线逐路变化（256 通道）","保护路线逐路变化（512 通道）","保护裕度分析","压力情景比较：最大损耗（×1 / ×2 / ×5 / ×10）","保护性局部优化执行记录","512 通道优化前后的关键指标","各口径下两个规模的最优配置与收益","证据等级定义","Top-U 主排序反转 A/B 结果","多交叉差分审计结果","精确几何 guard 实验的阶段与结果","局部精确恢复的四案例","只读审计的两项结论","排序与防护实验汇总（含证据等级）","本章负结果与未完成项","半径与路径结构改动的收益与代价","未布通情形","负结果清单","仍未验证的问题","二维实验总表","二维优化主线资料索引","二维原程序复现与诊断资料","早期二维阶段资料（Step 8 / 8.5）","汇总入口","正文表格—原始数据对应关系","正文插图—原始数据对应关系"]''')
sep = [i for i,l in enumerate(lines) if re.match(r"^\|\s*-{3,}", l)]
assert len(sep) == len(titles), (len(sep), len(titles))
out = list(lines)
for n in range(len(sep)-1, -1, -1):
    hdr = sep[n] - 1
    # already captioned?
    if out[hdr-1].strip().startswith("表"):
        continue
    out.insert(hdr, "表%d %s" % (n+1, titles[n]))
p.write_text("\n".join(out), encoding="utf-8")
print("inserted captions:", len(sep))
